struct LoopBounds {
    rocblas_int ki;
    rocblas_int kk;
    rocblas_int j_init;
};

LoopBounds compute_gerqf_bounds(rocblas_int k, rocblas_int nb, rocblas_int switchsize) {
    LoopBounds bounds;
    bounds.ki = ((k - switchsize - 1) / nb) * nb;
    bounds.kk = std::min(k, bounds.ki + nb);
    bounds.j_init = k - bounds.kk + bounds.ki;
    return bounds;
}
```
